using UnityEngine;
using UnityEngine.UI;
[RequireComponent(typeof(CanvasRenderer))]public sealed class GridShiftMapRouteGraphic:MaskableGraphic {
 public Camera mapCamera;public DeliveryManager manager;public RectTransform mapRect;float next;Vector3 cameraAt,vehicleAt;float size;CompanyVehicle vehicle;object path;
 protected override void Awake(){base.Awake();raycastTarget=false;color=new Color(.3f,.85f,1,.8f);}
 void LateUpdate(){if(Time.unscaledTime<next)return;next=Time.unscaledTime+.15f;if(manager==null||mapCamera==null)return;var tracked=manager.TrackedVehicle??(manager.Selected!=null?manager.fleet.Find(v=>v!=null&&v.Order==manager.Selected):null);if(tracked!=vehicle||tracked?.CurrentPath!=path||mapCamera.transform.position!=cameraAt||mapCamera.orthographicSize!=size||(tracked!=null&&(tracked.transform.position-vehicleAt).sqrMagnitude>.25f)){vehicle=tracked;path=tracked?.CurrentPath;cameraAt=mapCamera.transform.position;size=mapCamera.orthographicSize;vehicleAt=tracked!=null?tracked.transform.position:Vector3.zero;SetVerticesDirty();}}
 protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();if(vehicle==null||vehicle.Order==null||vehicle.CurrentPath==null||mapCamera==null||mapRect==null)return;var previous=vehicle.transform.position;bool current=false;foreach(var route in vehicle.CurrentPath){if(route==vehicle.driver.RotaAtual)current=true;if(!current||route==null)continue;int start=route==vehicle.driver.RotaAtual?vehicle.driver.NextPoint:0;for(int i=start;i<route.pontos.Length;i++){if(vehicle.Target!=null&&route==vehicle.Target.route&&i>=vehicle.Target.segment+1){Line(vh,previous,vehicle.Target.Stop);return;}var at=route.pontos[i].position;Line(vh,previous,at);previous=at;}}}
 void Line(VertexHelper vh,Vector3 a,Vector3 b){var p=mapCamera.WorldToViewportPoint(a);var q=mapCamera.WorldToViewportPoint(b);if(p.z<=0||q.z<=0||p.x<0||p.x>1||p.y<0||p.y>1||q.x<0||q.x>1||q.y<0||q.y>1)return;var r=mapRect.rect;var from=new Vector2((p.x-.5f)*r.width,(p.y-.5f)*r.height);var to=new Vector2((q.x-.5f)*r.width,(q.y-.5f)*r.height);var d=to-from;if(d.sqrMagnitude<.1f)return;var side=new Vector2(-d.y,d.x).normalized*1.3f;int n=vh.currentVertCount;vh.AddVert(from-side,color,Vector2.zero);vh.AddVert(from+side,color,Vector2.zero);vh.AddVert(to+side,color,Vector2.zero);vh.AddVert(to-side,color,Vector2.zero);vh.AddTriangle(n,n+1,n+2);vh.AddTriangle(n,n+2,n+3);}
}

